// In RouteFollower's constructor, in place of the route built from parameters.
using DriveRoute = bench_interfaces::action::DriveRoute;
using GoalHandle = rclcpp_action::ServerGoalHandle<DriveRoute>;

server_ = rclcpp_action::create_server<DriveRoute>(
    this, "~/drive_route",  // under the node's own name, as the relay's ~/drop is
    [this](const rclcpp_action::GoalUUID&, std::shared_ptr<const DriveRoute::Goal> goal) {
      return on_goal(*goal);
    },
    [this](std::shared_ptr<GoalHandle>) { return rclcpp_action::CancelResponse::ACCEPT; },
    [this](std::shared_ptr<GoalHandle> handle) { on_accepted(std::move(handle)); });

// A route is refused before it starts rather than abandoned halfway through.
rclcpp_action::GoalResponse on_goal(const DriveRoute::Goal& goal) {
  if (running_) return rclcpp_action::GoalResponse::REJECT;
  if (!bench::goals_from(goal.goals_x, goal.goals_y, goal.tolerance_m)) {
    RCLCPP_WARN(get_logger(), "goals_x and goals_y must be the same non-empty length");
    return rclcpp_action::GoalResponse::REJECT;
  }
  return rclcpp_action::GoalResponse::ACCEPT_AND_EXECUTE;
}

// First thing in on_odometry, once a goal is running. One stop command, then the supervisor's
// own timeout holds the robot: the follower does not keep publishing zeros after it has finished.
if (running_->handle->is_canceling()) {
  commands_->publish(stop_command(stamp));
  auto result = std::make_shared<DriveRoute::Result>();
  result->goals_reached = static_cast<std::int32_t>(running_->route.reached());
  running_->handle->canceled(result);
  running_.reset();
  return;
}

// In ScenarioRunner. The client spells the server's node out, because ~ here would expand
// against scenario_runner rather than route_follower, as the relay's client already does.
drive_client_ = rclcpp_action::create_client<DriveRoute>(this, "/route_follower/drive_route");

// Once the goal is accepted, send the route the scenario file describes.
auto goal = DriveRoute::Goal();
goal.goals_x = goals_x_;
goal.goals_y = goals_y_;
goal.tolerance_m = tolerance_m_;
auto options = rclcpp_action::Client<DriveRoute>::SendGoalOptions();
options.goal_response_callback = [this](ClientGoalHandle::SharedPtr handle) { goal_ = handle; };
drive_client_->async_send_goal(goal, options);

// In on_tick(), beside the drop cue: the cancel, once, at its moment, and only once the goal
// is accepted, so a cue is never spent on a goal the server has not answered for yet.
if (cancel_cue_ && goal_ && cancel_cue_->due(now_time.since_epoch - started_->since_epoch)) {
  cancel_at_ = now_time;
  drive_client_->async_cancel_goal(goal_);
}

#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <compare>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <ranges>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

namespace bench {

// From bench/time.hpp, bench/drive.hpp and bench/scenario.hpp, as the earlier topics left them.
struct Time {
  std::chrono::nanoseconds since_epoch;
  auto operator<=>(const Time&) const = default;
};

struct Goal {
  double x_m = 0.0;
  double y_m = 0.0;
  double tolerance_m = 0.10;
};

struct Sample {
  Time at;
  double x_m = 0.0;
  double y_m = 0.0;
  double speed_mps = 0.0;
};

enum class Compare { at_least, at_most };

struct Check {
  std::string what;
  std::string unit;
  Compare compare;
  double limit;
  std::optional<double> measured;
};

[[nodiscard]] bool met(const Check& check) {
  if (!check.measured) return false;
  return check.compare == Compare::at_least ? *check.measured >= check.limit : *check.measured <= check.limit;
}

struct Verdict {
  std::string scenario;
  std::int64_t samples;
  bool passed;
  std::vector<Check> checks;
};

[[nodiscard]] Verdict judge(std::string scenario, std::int64_t samples, std::vector<Check> checks) {
  const bool passed = std::ranges::all_of(checks, met);
  return {.scenario = std::move(scenario), .samples = samples, .passed = passed, .checks = std::move(checks)};
}

namespace {

[[nodiscard]] double seconds(std::chrono::nanoseconds d) { return std::chrono::duration<double>(d).count(); }

[[nodiscard]] std::string with_unit(double value, std::string_view unit) {
  return unit.empty() ? std::format("{:.2f}", value) : std::format("{:.2f} {}", value, unit);
}

[[nodiscard]] std::string line(const Check& check) {
  const std::string measured = check.measured ? with_unit(*check.measured, check.unit) : std::string("not measured");
  return std::format("{:<6} {}: {}, {} {}\n", met(check) ? "ok" : "failed", check.what, measured,
                     check.compare == Compare::at_least ? "at least" : "at most", with_unit(check.limit, check.unit));
}

}  // namespace

[[nodiscard]] std::string describe(const Verdict& verdict) {
  std::string text = std::format("{}\nscenario: {}\nsamples: {}\n", verdict.passed ? "pass" : "fail",
                                 verdict.scenario, verdict.samples);
  for (const Check& check : verdict.checks) text += line(check);
  return text;
}

[[nodiscard]] double range_m(const Sample& sample, const Goal& goal) {
  return std::hypot(goal.x_m - sample.x_m, goal.y_m - sample.y_m);
}

[[nodiscard]] std::optional<double> top_speed_mps(std::span<const Sample> run) {
  if (run.empty()) return std::nullopt;
  return std::ranges::max(run | std::views::transform([](const Sample& s) { return std::abs(s.speed_mps); }));
}

[[nodiscard]] std::span<const Sample> since(std::span<const Sample> run, Time from) {
  return {std::ranges::lower_bound(run, from, {}, &Sample::at), run.end()};
}

[[nodiscard]] std::span<const Sample> between(std::span<const Sample> run, Time from, Time to) {
  const auto first = std::ranges::lower_bound(run, from, {}, &Sample::at);
  const auto last = std::ranges::upper_bound(run, to, {}, &Sample::at);
  if (first >= last) return {};
  return {first, last};
}

[[nodiscard]] std::optional<Time> reached_at(std::span<const Sample> run, const Goal& goal) {
  const auto inside =
      std::ranges::find_if(run, [&goal](const Sample& s) { return range_m(s, goal) <= goal.tolerance_m; });
  if (inside == run.end()) return std::nullopt;
  return inside->at;
}

[[nodiscard]] std::vector<Time> goal_times(std::span<const Sample> run, std::span<const Goal> goals) {
  std::vector<Time> times;
  std::span<const Sample> rest = run;
  for (const Goal& goal : goals) {
    const std::optional<Time> at = reached_at(rest, goal);
    if (!at) break;
    times.push_back(*at);
    rest = since(rest, *at);
  }
  return times;
}

[[nodiscard]] std::optional<Time> first_rest(std::span<const Sample> run, double speed_limit_mps,
                                             std::chrono::nanoseconds for_at_least) {
  std::optional<Time> start;
  for (const Sample& sample : run) {
    if (std::abs(sample.speed_mps) > speed_limit_mps) {
      start.reset();
      continue;
    }
    if (!start) start = sample.at;
    if (sample.at.since_epoch - start->since_epoch >= for_at_least) return start;
  }
  return std::nullopt;
}

[[nodiscard]] std::optional<double> wandered_m(std::span<const Sample> run) {
  if (run.empty()) return std::nullopt;
  const Sample& start = run.front();
  return std::ranges::max(run | std::views::transform([&start](const Sample& s) {
                            return std::hypot(s.x_m - start.x_m, s.y_m - start.y_m);
                          }));
}

// New in this topic.

// What a cancelled mission has to do. The first three limits are the missing-odometry ones under
// another name, because a cancel and a lost input ask the robot for the same thing.
struct CancelLimits {
  std::chrono::nanoseconds before;   // the window before the cancel in which the robot must be driving
  double driving_mps;                // the speed that proves it was driving when the cancel arrived
  std::chrono::nanoseconds to_rest;  // from the cancel until the robot is at rest
  double creep_m;                    // from the cancel to the end of the run, not only to rest
};

[[nodiscard]] std::vector<Check> cancel_checks(std::span<const Sample> run, std::span<const Goal> goals,
                                               std::optional<Time> cancel, const CancelLimits& limits) {
  using namespace std::chrono_literals;
  const std::optional<Time> rest = cancel ? first_rest(since(run, *cancel), 0.01, 300ms) : std::nullopt;
  const auto to_rest = [&]() -> std::optional<double> {
    if (!rest || !cancel) return std::nullopt;
    return seconds(rest->since_epoch - cancel->since_epoch);
  };
  const auto was_driving = [&]() -> std::optional<double> {
    if (!cancel) return std::nullopt;
    return top_speed_mps(between(run, {cancel->since_epoch - limits.before}, *cancel));
  };
  // From the cancel to the end of the run, so a robot that stopped and then carried on is caught
  // by the same number as one that never stopped.
  const auto after = [&]() -> std::optional<double> {
    if (!cancel) return std::nullopt;
    return wandered_m(since(run, *cancel));
  };
  const auto more_goals = [&]() -> std::optional<double> {
    if (!cancel) return std::nullopt;
    return static_cast<double>(std::ssize(goal_times(since(run, *cancel), goals)));
  };
  return {{.what = "the cancel went out at",
           .unit = "s",
           .compare = Compare::at_least,
           .limit = 0.0,
           .measured = cancel ? std::optional<double>(seconds(cancel->since_epoch)) : std::nullopt},
          {.what = "top speed in the second before the cancel",
           .unit = "m/s",
           .compare = Compare::at_least,
           .limit = limits.driving_mps,
           .measured = was_driving()},
          {.what = "time from the cancel to the robot at rest",
           .unit = "s",
           .compare = Compare::at_most,
           .limit = seconds(limits.to_rest),
           .measured = to_rest()},
          {.what = "distance from the cancel point to the end of the run",
           .unit = "m",
           .compare = Compare::at_most,
           .limit = limits.creep_m,
           .measured = after()},
          {.what = "goals reached after the cancel",
           .unit = "",
           .compare = Compare::at_most,
           .limit = 0.0,
           .measured = more_goals()}};
}

}  // namespace bench

// One odometry message of a made-up run, half a second of simulated time apart.
struct Moment {
  std::chrono::milliseconds t;
  double x_m;
  double y_m;
  double speed_mps;
};

[[nodiscard]] std::vector<bench::Sample> samples(std::span<const Moment> moments) {
  std::vector<bench::Sample> run;
  for (const Moment& moment : moments) {
    run.push_back({.at = {moment.t}, .x_m = moment.x_m, .y_m = moment.y_m, .speed_mps = moment.speed_mps});
  }
  return run;
}

int main() {
  using namespace std::chrono_literals;
  constexpr std::array<bench::Goal, 2> goals{{{.x_m = 0.80, .y_m = 0.00, .tolerance_m = 0.10},
                                              {.x_m = 0.80, .y_m = 0.50, .tolerance_m = 0.10}}};
  constexpr bench::CancelLimits limits{
      .before = 1000ms, .driving_mps = 0.10, .to_rest = 1500ms, .creep_m = 0.25};
  const std::optional<bench::Time> cancel{bench::Time{4000ms}};

  // The server obeying: the cancel arrives at 4.0 s, the robot brakes and stays where it stopped.
  constexpr std::array<Moment, 11> obeyed{{{.t = 3000ms, .x_m = 0.30, .y_m = 0.00, .speed_mps = 0.20},
                                           {.t = 3500ms, .x_m = 0.40, .y_m = 0.00, .speed_mps = 0.20},
                                           {.t = 4000ms, .x_m = 0.50, .y_m = 0.00, .speed_mps = 0.20},
                                           {.t = 4500ms, .x_m = 0.57, .y_m = 0.00, .speed_mps = 0.08},
                                           {.t = 5000ms, .x_m = 0.58, .y_m = 0.00, .speed_mps = 0.00},
                                           {.t = 5500ms, .x_m = 0.58, .y_m = 0.00, .speed_mps = 0.00},
                                           {.t = 6000ms, .x_m = 0.58, .y_m = 0.00, .speed_mps = 0.00},
                                           {.t = 6500ms, .x_m = 0.58, .y_m = 0.00, .speed_mps = 0.00},
                                           {.t = 7000ms, .x_m = 0.58, .y_m = 0.00, .speed_mps = 0.00},
                                           {.t = 7500ms, .x_m = 0.58, .y_m = 0.00, .speed_mps = 0.00},
                                           {.t = 8000ms, .x_m = 0.58, .y_m = 0.00, .speed_mps = 0.00}}};
  const auto stopped = samples(obeyed);
  std::cout << bench::describe(
      bench::judge("cancel", std::ssize(stopped), bench::cancel_checks(stopped, goals, cancel, limits)));
  std::cout << '\n';

  // A server that never looks at is_canceling(): the route runs to the end as though nothing
  // had been asked of it.
  constexpr std::array<Moment, 11> ignored{{{.t = 3000ms, .x_m = 0.30, .y_m = 0.00, .speed_mps = 0.20},
                                            {.t = 3500ms, .x_m = 0.40, .y_m = 0.00, .speed_mps = 0.20},
                                            {.t = 4000ms, .x_m = 0.50, .y_m = 0.00, .speed_mps = 0.20},
                                            {.t = 4500ms, .x_m = 0.60, .y_m = 0.00, .speed_mps = 0.20},
                                            {.t = 5000ms, .x_m = 0.70, .y_m = 0.00, .speed_mps = 0.20},
                                            {.t = 5500ms, .x_m = 0.72, .y_m = 0.05, .speed_mps = 0.20},
                                            {.t = 6000ms, .x_m = 0.75, .y_m = 0.20, .speed_mps = 0.20},
                                            {.t = 6500ms, .x_m = 0.78, .y_m = 0.35, .speed_mps = 0.20},
                                            {.t = 7000ms, .x_m = 0.79, .y_m = 0.45, .speed_mps = 0.05},
                                            {.t = 7500ms, .x_m = 0.79, .y_m = 0.45, .speed_mps = 0.00},
                                            {.t = 8000ms, .x_m = 0.79, .y_m = 0.45, .speed_mps = 0.00}}};
  const auto drove_on = samples(ignored);
  std::cout << bench::describe(
      bench::judge("cancel", std::ssize(drove_on), bench::cancel_checks(drove_on, goals, cancel, limits)));
}
